tinymce.PluginManager.add("filemanager", function (editor, url) {
    editor.ui.registry.addIcon('folder', '<svg height="24" viewBox="0 0 48 48" width="24" xmlns="http://www.w3.org/2000/svg"><path d="M0 0h48v48h-48z" fill="none"/><path d="M40 12h-16l-4-4h-12c-2.21 0-3.98 1.79-3.98 4l-.02 24c0 2.21 1.79 4 4 4h32c2.21 0 4-1.79 4-4v-20c0-2.21-1.79-4-4-4zm0 24h-32v-20h32v20z"/></svg>');
    editor.ui.registry.addButton("filemanager", {
        title: "File manager",
        icon: "folder",
        onAction: function () {
            editor.windowManager.openUrl({
                title: 'File manager',
                url: "/filemanager/tinymce",
                width: window.innerWidth * 0.9,
                height: window.innerHeight * 0.8,
            });
        }
    })
});